73	function resolveTaskRepoId(workspaceRoot: string, featureId: string, taskId: string): string {
74	  const task = parseYaml(
75	    readFileSync(taskYamlAbsPath(workspaceRoot, featureId, taskId), "utf-8"),
76	  ) as { repo: string };
77	  if (!task.repo) throw new Error(`Task ${taskId} has no repo field`);
