118	function writeRagPreFlight(
119	  workspaceRoot: string,
120	  featureId: string,
121	  taskId: string,
122	  taskBranch: string,
123	  gitAuthorEmail: string,
124	  gitAuthorName: string,
125	  sshKeyPath: string | undefined,
126	  ragPreFlight: { query: string; injected: boolean; summary: string },
127	): void {
128	  const now = new Date().toISOString();
129	  const entry: TaskLogEntry = {
130	    action: "rag_pre_flight",
131	    by: gitAuthorEmail,
132	    at: now,
133	    rag_context_injected: ragPreFlight.injected,
134	    rag_summary: ragPreFlight.summary,
135	    rag_query: ragPreFlight.query,
136	    note: "Runtime pre-flight RAG fetch — written before executor spawn.",
137	  };
138	
139	  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
140	  const task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
141	  task.log.push(entry);
142	  writeFileSync(yamlPath, yamlStringify(task), "utf-8");
143	
144	  const relPath = taskYamlRelPath(featureId, taskId);
145	  const gitOpts = {
146	    cwd: workspaceRoot,
147	    encoding: "utf-8" as const,
148	    env: buildGitCommitEnv(gitAuthorEmail, gitAuthorName, sshKeyPath),
149	    timeout: 30_000,
150	    stdio: "pipe" as const,
151	  };
152	  execSync(`git add "${relPath}"`, gitOpts);
153	  execSync(
154	    `git commit -m "chore(${taskId}): rag pre-flight — ${ragPreFlight.injected ? "injected" : "skipped"}"`,
155	    gitOpts,
156	  );
157	  execSync(`git push origin "${taskBranch}"`, gitOpts);
158	}
