/**
 * LocalFileBriefingAdapter — BriefingTransportPort adapter.
 *
 * Writes briefing content to a temp file on the shared host filesystem.
 * The executor reads the file via the path returned from put().
 * Suitable for local-subprocess and local-docker (shared host volume).
 */

import { writeFileSync, unlinkSync, mkdirSync, existsSync } from "node:fs";
import { join } from "node:path";
import { tmpdir } from "node:os";
import type { BriefingTransportPort, ExecutorHandle } from "@workflow/runtime-abi";

export interface LocalFileBriefingAdapterOpts {
  /** Base directory for briefing files. Defaults to os.tmpdir(). */
  baseDir?: string;
}

export class LocalFileBriefingAdapter implements BriefingTransportPort {
  private readonly baseDir: string;

  constructor(opts: LocalFileBriefingAdapterOpts = {}) {
    this.baseDir = opts.baseDir ?? tmpdir();
  }

  async put(handle: ExecutorHandle, content: string): Promise<string> {
    const briefingDir = join(this.baseDir, `briefing-${handle}`);
    mkdirSync(briefingDir, { recursive: true });
    const briefingPath = join(briefingDir, "briefing.md");
    writeFileSync(briefingPath, content, "utf-8");
    return briefingPath;
  }

  async cleanup(handle: ExecutorHandle): Promise<void> {
    const briefingDir = join(this.baseDir, `briefing-${handle}`);
    const briefingPath = join(briefingDir, "briefing.md");
    try {
      if (existsSync(briefingPath)) unlinkSync(briefingPath);
    } catch {
      // best-effort cleanup
    }
  }
}

