1	/**
2	 * Orchestrator side-effect: write terminal task status to the task YAML.
3	 *
4	 * Called after the executor returns a result. Translates ExecutorResult
5	 * terminal_status values into the workflow task status schema and commits
6	 * the change to the management repo's task branch.
7	 */
8	
9	import { readFileSync, writeFileSync } from "node:fs";
10	import { execSync, spawnSync } from "node:child_process";
11	import { parse as parseYaml, stringify as yamlStringify } from "yaml";
12	import type { Task } from "../types/task.js";
13	import type { ExecutorResult } from "@workflow/runtime-abi";
14	import { taskYamlAbsPath, taskYamlRelPath } from "../paths.js";
15	import { buildGitCommitEnv } from "../git-env.js";
16	
17	export interface MutateTaskYamlOpts {
18	  workspaceRoot: string;
19	  featureId: string;
20	  taskId: string;
21	  taskBranch: string;
22	  result: ExecutorResult;
23	  /**
24	   * Implementation repo PR URL — reported by the executor in result.json.pr_url.
25	   * Recorded whenever present, regardless of terminal_status. A blocked task
26	   * with a draft PR still records its pr_url.
27	   */
28	  prUrl?: string;
29	  gitAuthorEmail: string;
30	  gitAuthorName?: string;
31	  sshKeyPath?: string;
32	}
33	
34	/**
35	 * Write the terminal task status implied by ExecutorResult to the task YAML
36	 * and commit+push to the task branch.
37	 *
38	 * Status transitions:
39	 *   in_review → task.status = "in_review", task.pr.url = prUrl (when present)
40	 *   blocked   → task.status = "blocked", task.blocked_reason + task.blocked_suggestion
41	 *               task.pr.url = prUrl when present (draft PR documents failed attempt)
42	 *   failed    → task.status = "blocked", task.blocked_reason = "executor_failed:<reason>"
43	 *               task.pr.url = prUrl when present
44	 *
45	 * Non-throwing: returns an error string on failure so the caller can decide
46	 * whether to surface or swallow the error.
47	 */
48	export function mutateTaskYaml(opts: MutateTaskYamlOpts): string | undefined {
49	  const {
50	    workspaceRoot,
51	    featureId,
52	    taskId,
53	    taskBranch,
54	    result,
55	    prUrl,
56	    gitAuthorEmail,
57	    gitAuthorName = gitAuthorEmail,
58	    sshKeyPath,
59	  } = opts;
60	
61	  const now = new Date().toISOString();
62	  const yamlPath = taskYamlAbsPath(workspaceRoot, featureId, taskId);
63	  let task: Task;
64	  try {
65	    task = parseYaml(readFileSync(yamlPath, "utf-8")) as Task;
66	  } catch (e) {
67	    return `failed to read task YAML: ${String(e)}`;
68	  }
69	
70	  task.execution.last_updated_by = gitAuthorEmail;
71	  task.execution.last_updated_at = now;
72	
73	  switch (result.terminal_status) {
74	    case "in_review":
75	      task.status = "in_review";
76	      break;
77	
78	    case "blocked":
79	      task.status = "blocked";
80	      task.blocked_reason = result.blocked_reason ?? "unknown";
81	      if (result.blocked_suggestion) {
82	        task.blocked_suggestion = result.blocked_suggestion;
83	      }
84	      break;
85	
86	    case "failed":
87	      task.status = "blocked";
88	      task.blocked_reason = `executor_failed:${result.blocked_reason ?? "unknown"}`;
89	      if (result.blocked_suggestion) {
90	        task.blocked_suggestion = result.blocked_suggestion;
91	      }
92	      break;
93	  }
94	
95	  // Record pr_url on any terminal_status — executor reports it whenever a PR was opened.
96	  // A blocked task with a draft PR still records pr.url so the failed attempt is documented.
97	  if (prUrl) {
98	    task.pr = { url: prUrl, status: "open" };
99	  }
100	
101	  try {
102	    writeFileSync(yamlPath, yamlStringify(task), "utf-8");
103	  } catch (e) {
104	    return `failed to write task YAML: ${String(e)}`;
105	  }
106	
107	  const relPath = taskYamlRelPath(featureId, taskId);
108	  const env = buildGitCommitEnv(gitAuthorEmail, gitAuthorName, sshKeyPath);
109	  const statusLabel = result.terminal_status === "in_review" ? "in_review" : "blocked";
110	
111	  try {
112	    execSync(`git -C "${workspaceRoot}" add "${relPath}"`, { env, stdio: "pipe" });
113	    execSync(
114	      `git -C "${workspaceRoot}" commit -m "chore(${taskId}): status → ${statusLabel}"`,
115	      { env, stdio: "pipe" },
116	    );
117	  } catch (e) {
118	    return `git add/commit failed: ${String(e)}`;
119	  }
